<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ChevronRight,Plus,Search}from'lucide-vue-next';import ModalDialog from'@/components/ModalDialog.vue';import StatusBadge from'@/components/StatusBadge.vue';import EmptyState from'@/components/EmptyState.vue';import{api}from'@/services/api';import{errorMessage}from'@/services/http';import type{Train}from'@/types';const items=ref<Train[]>([]),keyword=ref(''),open=ref(false),message=ref('');const form=reactive({trainNo:'',name:''});async function load(){try{items.value=await api.trains(keyword.value)}catch(e){message.value=errorMessage(e)}}async function add(){try{await api.createTrain(form);open.value=false;Object.assign(form,{trainNo:'',name:''});await load()}catch(e){message.value=errorMessage(e)}}async function toggle(i:Train){try{await api.trainStatus(i.id,i.status?0:1);await load()}catch(e){message.value=errorMessage(e)}}onMounted(load)
</script>
<template><section class="admin-page"><header class="page-head"><div><p class="eyebrow">TRAINS</p><h1>车次管理</h1><p>维护列车基础信息并进入详情配置票务数据</p></div><button class="btn primary" @click="open=true"><Plus/>新增车次</button></header><div class="toolbar"><label class="search-input"><Search/><input v-model="keyword" placeholder="搜索车次号或名称" @keyup.enter="load"></label><button class="btn ghost" @click="load">搜索</button></div><p v-if="message" class="notice error">{{message}}</p><div v-if="items.length" class="train-admin-grid"><article v-for="i in items" :key="i.id"><div class="train-number">{{i.trainNo.slice(0,1)}}</div><div><h3>{{i.trainNo}}</h3><p>{{i.name}}</p><StatusBadge :active="i.status===1"/></div><div class="card-actions"><button class="link-btn" @click="toggle(i)">{{i.status?'停用':'启用'}}</button><RouterLink :to="`/admin/trains/${i.id}`" class="icon-btn"><ChevronRight/></RouterLink></div></article></div><EmptyState v-else/><ModalDialog :open="open" title="新增车次" @close="open=false"><form class="stack-form" @submit.prevent="add"><label>车次号<input v-model.trim="form.trainNo" required placeholder="如 G101"></label><label>车次名称<input v-model.trim="form.name" required placeholder="如 京沪高速动车组"></label><button class="btn primary wide">保存车次</button></form></ModalDialog></section></template>
